-- assert (luassert's API). Every test name ends with the outcome it must have.

describe("assert", function()
    it("equality (ok)", function()
        assert.equals(1, 1)
        assert.equal("a", "a")
        assert.are.equal(2, 2)
        assert.are_not.equal(1, 2)
        assert.is_not.equal(1, 2)
        assert.not_equals(1, 2)
        assert.same({ 1, { 2, 3 } }, { 1, { 2, 3 } })
        assert.are.same({ a = { b = true } }, { a = { b = true } })
        assert.are_not.same({ 1 }, { 2 })
        assert.near(1.0, 1.05, 0.1)
        assert.is_not.near(1.0, 2.0, 0.1)
    end)

    it("truth and types (ok)", function()
        assert.truthy(0)
        assert.is_truthy("")
        assert.falsy(nil)
        assert.is_falsy(false)
        assert.is_true(true)
        assert.is_false(false)
        assert.is_not_true(1)
        assert.is_nil(nil)
        assert.is_not_nil(0)
        assert.is_number(1)
        assert.is_string("s")
        assert.is_table({})
        assert.is_function(print)
        assert.is_boolean(false)
        assert.is_not.number("1")
        assert.unique({ 1, 2, 3 })
        assert.is_not.unique({ 1, 1 })
    end)

    it("errors (ok)", function()
        assert.has_error(function() error("boom") end)
        assert.has_error(function() error("boom", 0) end, "boom")
        assert.has.errors(function() error({ code = 7 }) end, { code = 7 })
        assert.error_matches(function() error("code 42 here") end, "code %d+")
        assert.has_no.errors(function() end)
        assert.has_no_error(function() return 1 end)
        assert.is_not.error_matches(function() error("other") end, "^code")
    end)

    it("strings (ok)", function()
        assert.matches("^ab", "abc")
        assert.is_not.matches("^b", "abc")
        assert.matches("a.c", "a.c", 1, true)
    end)

    it("matchers in same (ok)", function()
        assert.same({ id = match._, name = match.is_string() }, { id = 3, name = "x" })
        assert.same({ 1, match.is_number(), match.is_not_nil() }, { 1, 2.5, false })
        assert.same(match.table_containing({ a = 1 }), { a = 1, b = 2 })
        assert.same(match.all_of(match.is_number(), match.is_not.equal(3)), 4)
        assert.same(match.any_of(match.is_string(), match.is_nil()), nil)
        assert.same(match.none_of(match.is_string()), 5)
        assert.same(match.contains(2), { 1, 2, 3 })
    end)

    it("matchers nested in match.same, contains and table_containing (ok)", function()
        assert.same(match.same({ id = match.is_number() }), { id = 5 })
        assert.same(match.table_containing({ pos = { x = match._ } }), { pos = { x = 1 }, hp = 2 })
        assert.same(match.contains({ kind = match.is_string() }), { { kind = "orc" }, 3 })
        expect({ { kind = "orc" } }).to.contain({ kind = match.is_string() })
    end)

    it("a custom matcher may return any truthy value (ok)", function()
        assert:register("matcher", "has_x", function(_, args)
            return function(v) return type(v) == "string" and string.find(v, "x", 1, true) end
        end)
        assert.same({ name = match.has_x() }, { name = "box" })
        assert.same({ name = match.is_not.has_x() }, { name = "bag" })
    end)

    it("custom assertion (ok)", function()
        assert:register("assertion", "even", function(_, args) return args[1] % 2 == 0 end,
            "Expected an even number:\n%s", "Expected an odd number:\n%s")
        assert.is_even(4)
        assert.is_not_even(3)
    end)

    it("a message argument (fails)", function()
        assert.equals(1, 2, "the custom message")
    end)

    it("near with a tolerance (fails)", function()
        assert.near(1.0, 1.5, 0.1)
    end)

    it("has_error without an error (fails)", function()
        assert.has_error(function() end)
    end)

    it("an error from a test is an error (errors)", function()
        error("not an assertion")
    end)

    it("an error with a table value (errors)", function()
        error({ code = 9 })
    end)

    it("is_true on 1 (fails)", function()
        assert.is_true(1)
    end)

    it("not same (fails)", function()
        assert.are_not.same({ 1 }, { 1 })
    end)
end)
